import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  addedAt: string;
  finishedAt: string | null;
};

export type NewBook = Pick<Book, "title" | "author" | "notes">;

function dataFile() {
  return process.env.BOOKS_FILE ?? path.join(process.cwd(), "data", "books.json");
}

async function readAll(): Promise<Book[]> {
  try {
    return JSON.parse(await readFile(dataFile(), "utf8"));
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw err;
  }
}

// Write to a temp file and rename, so a crash mid-write can't leave a
// half-written books.json behind.
async function writeAll(books: Book[]) {
  const file = dataFile();
  await mkdir(path.dirname(file), { recursive: true });
  const tmp = `${file}.${process.pid}.tmp`;
  await writeFile(tmp, JSON.stringify(books, null, 2) + "\n");
  await rename(tmp, file);
}

// Serialize read-modify-write cycles so two quick submissions can't
// overwrite each other's changes.
let queue: Promise<unknown> = Promise.resolve();
function update<T>(fn: (books: Book[]) => T | Promise<T>): Promise<T> {
  const run = queue.then(async () => {
    const books = await readAll();
    const result = await fn(books);
    await writeAll(books);
    return result;
  });
  queue = run.catch(() => {});
  return run;
}

export async function listBooks(): Promise<Book[]> {
  return readAll();
}

export async function getBook(id: string): Promise<Book | undefined> {
  return (await readAll()).find((b) => b.id === id);
}

export function addBook(input: NewBook): Promise<Book> {
  return update((books) => {
    const book: Book = {
      id: randomUUID(),
      title: input.title,
      author: input.author,
      notes: input.notes,
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.push(book);
    return book;
  });
}

export function markFinished(id: string): Promise<Book | undefined> {
  return update((books) => {
    const book = books.find((b) => b.id === id);
    if (book && !book.finishedAt) book.finishedAt = new Date().toISOString();
    return book;
  });
}

