"use server";

import { revalidatePath } from "next/cache";
import * as books from "@/lib/books";

export type AddBookState = { error?: string; ok?: boolean };

const LIMITS = { title: 300, author: 200, notes: 10_000 };

function field(form: FormData, name: keyof typeof LIMITS) {
  const value = form.get(name);
  return typeof value === "string" ? value.trim() : "";
}

export async function addBook(_prev: AddBookState, form: FormData): Promise<AddBookState> {
  const title = field(form, "title");
  const author = field(form, "author");
  const notes = field(form, "notes");

  if (!title) return { error: "Title is required." };
  if (!author) return { error: "Author is required." };
  for (const [name, value] of Object.entries({ title, author, notes })) {
    if (value.length > LIMITS[name as keyof typeof LIMITS]) {
      return { error: `${name[0].toUpperCase() + name.slice(1)} is too long.` };
    }
  }

  await books.addBook({ title, author, notes });
  revalidatePath("/");
  return { ok: true };
}

export async function markFinished(id: string) {
  await books.markFinished(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

