"use client";

import { useActionState, useEffect, useRef } from "react";
import { addBook, type AddBookState } from "./actions";

export function AddBookForm() {
  const [state, action, pending] = useActionState<AddBookState, FormData>(addBook, {});
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (state.ok) formRef.current?.reset();
  }, [state]);

  return (
    <form ref={formRef} action={action} className="add-form">
      <label>
        Title
        <input name="title" required maxLength={300} />
      </label>
      <label>
        Author
        <input name="author" required maxLength={200} />
      </label>
      <label>
        Notes
        <textarea name="notes" rows={3} maxLength={10000} />
      </label>
      {state.error && <p className="error">{state.error}</p>}
      <button type="submit" disabled={pending}>
        {pending ? "Adding…" : "Add book"}
      </button>
    </form>
  );
}

