import Link from "next/link";
import { connection } from "next/server";
import { listBooks, type Book } from "@/lib/books";
import { AddBookForm } from "./add-book-form";
import { MarkFinishedButton } from "./mark-finished-button";

export default async function Home() {
  await connection();
  const books = await listBooks();
  const reading = books.filter((b) => !b.finishedAt);
  const finished = books
    .filter((b) => b.finishedAt)
    .sort((a, b) => b.finishedAt!.localeCompare(a.finishedAt!));

  return (
    <main>
      <h1>My books</h1>

      <section>
        <h2>Currently reading</h2>
        <BookList books={reading} empty="Nothing on the go." showFinish />
      </section>

      <section>
        <h2>Finished</h2>
        <BookList books={finished} empty="No finished books yet." />
      </section>

      <section>
        <h2>Add a book</h2>
        <AddBookForm />
      </section>
    </main>
  );
}

function BookList({ books, empty, showFinish }: { books: Book[]; empty: string; showFinish?: boolean }) {
  if (books.length === 0) return <p className="muted">{empty}</p>;
  return (
    <ul className="books">
      {books.map((book) => (
        <li key={book.id}>
          <Link href={`/books/${book.id}`}>
            <strong>{book.title}</strong> <span className="muted">by {book.author}</span>
          </Link>
          {showFinish && <MarkFinishedButton id={book.id} />}
        </li>
      ))}
    </ul>
  );
}

