import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { getBook } from "@/lib/books";
import { CopyLinkButton } from "../../copy-link-button";
import { MarkFinishedButton } from "../../mark-finished-button";

type Props = { params: Promise<{ id: string }> };

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const book = await getBook((await params).id);
  return { title: book ? `${book.title} – My books` : "Book not found" };
}

export default async function BookPage({ params }: Props) {
  const book = await getBook((await params).id);
  if (!book) notFound();

  return (
    <main>
      <p>
        <Link href="/">← All books</Link>
      </p>
      <h1>{book.title}</h1>
      <p className="muted">by {book.author}</p>
      <p>
        {book.finishedAt
          ? `Finished ${new Date(book.finishedAt).toLocaleDateString("en-GB", { dateStyle: "long" })}`
          : "Currently reading"}
      </p>

      <h2>Notes</h2>
      {book.notes ? <p className="notes">{book.notes}</p> : <p className="muted">No notes.</p>}

      <div className="actions">
        <CopyLinkButton />
        {!book.finishedAt && <MarkFinishedButton id={book.id} />}
      </div>
    </main>
  );
}

