import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, expect, test } from "vitest";
import { addBook, getBook, listBooks, markFinished } from "./books";

let dir: string;

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), "books-"));
  process.env.BOOKS_FILE = path.join(dir, "nested", "books.json");
});

afterEach(async () => {
  delete process.env.BOOKS_FILE;
  await rm(dir, { recursive: true, force: true });
});

test("starts empty when the file doesn't exist", async () => {
  expect(await listBooks()).toEqual([]);
});

test("adds a book and persists it to disk", async () => {
  const book = await addBook({ title: "Dune", author: "Frank Herbert", notes: "Spice." });
  expect(book.finishedAt).toBeNull();
  expect(await getBook(book.id)).toEqual(book);

  const onDisk = JSON.parse(await readFile(process.env.BOOKS_FILE!, "utf8"));
  expect(onDisk).toEqual([book]);
});

test("marks a book finished", async () => {
  const book = await addBook({ title: "Emma", author: "Jane Austen", notes: "" });
  const finished = await markFinished(book.id);
  expect(finished?.finishedAt).toEqual(expect.any(String));
  expect((await getBook(book.id))?.finishedAt).toBe(finished?.finishedAt);
});

test("marking an unknown id is a no-op", async () => {
  expect(await markFinished("nope")).toBeUndefined();
  expect(await listBooks()).toEqual([]);
});

test("concurrent adds don't lose writes", async () => {
  await Promise.all(
