import { chromium } from "playwright";

const base = "http://localhost:3100";
const browser = await chromium.launch();
const ctx = await browser.newContext({ permissions: ["clipboard-read", "clipboard-write"] });
const page = await ctx.newPage();
const log = (...a) => console.log(...a);

await page.goto(base);
await page.fill('input[name="title"]', "Middlemarch");
await page.fill('input[name="author"]', "George Eliot");
await page.fill('textarea[name="notes"]', "Line one\nLine two <script>alert(1)</script>");
await page.click('button:has-text("Add book")');
await page.waitForSelector('a:has-text("Middlemarch")');
log("form reset:", (await page.inputValue('input[name="title"]')) === "");

// whitespace-only title should be rejected server-side
await page.fill('input[name="title"]', "   ");
await page.fill('input[name="author"]', "x");
await page.click('button:has-text("Add book")');
await page.waitForSelector(".error");
log("error shown:", await page.textContent(".error"));

await page.fill('input[name="title"]', "Dune");
await page.fill('input[name="author"]', "Frank Herbert");
await page.click('button:has-text("Add book")');
await page.waitForSelector('a:has-text("Dune")');

await page.click('a:has-text("Middlemarch")');
await page.waitForSelector("h1:has-text('Middlemarch')");
const url = page.url();
log("detail url:", url);
log("notes:", JSON.stringify(await page.textContent(".notes")));
await page.click('button:has-text("Copy link")');
log("clipboard:", await page.evaluate(() => navigator.clipboard.readText()));
await page.click('button:has-text("Mark finished")');
await page.waitForSelector("text=Finished ");
log("status:", await page.textContent("main > p:nth-of-type(3)"));

// fresh context = someone you sent the link to
const other = await (await browser.newContext()).newPage();
await other.goto(url);
log("shared link title:", await other.textContent("h1"), "|", await other.title());

await page.goto(base);
const sections = await page.$$eval("section", (s) =>
  s.slice(0, 2).map((x) => x.innerText.replace(/\s+/g, " ").trim()),
);
log(sections);

// mark finished from the list
await page.click('li:has-text("Dune") button:has-text("Mark finished")');
await page.waitForSelector("text=Nothing on the go.");
log("after finishing Dune from list ok");
await browser.close();

